            cout << "   " << n << " (suma=" << s << ")" << endl;
            ileA++;
        }
    }
    cout << "   Ilosc: " << ileA << endl;

    // b)
    cout << endl << "b) Pierwsza cyfra > ostatnia:" << endl;
    int ileB = 0;
    for (int n : tab) {
        int pierwsza = n;
        while (pierwsza >= 10) pierwsza /= 10;
        int ostatnia = n % 10;
        if (pierwsza > ostatnia) {
            cout << "   " << n << " (" << pierwsza << ">" << ostatnia << ")" << endl;
            ileB++;
        }
    }
    cout << "   Ilosc: " << ileB << endl;

